import { createServer } from "node:http";

type StatusUpdate = { message: string };
const latest: StatusUpdate[] = [];
const limit = 16 * 1024;

export const server = createServer(function handle(request, response) {
    if (request.method !== "POST" || request.url !== "/status") {
        response.writeHead(404, { "content-type": "application/json" });
        response.end(JSON.stringify({ error: "not_found" }));
        return;
    }

    let size = 0;
    let rejected = false;
    const chunks: Buffer[] = [];
    request.on("data", function onChunk(chunk: Buffer) {
        if (rejected) {
            return;
        }
        size += chunk.length;
        if (size > limit) {
            rejected = true;
            chunks.length = 0;
            response.writeHead(413, { "content-type": "application/json" });
            response.end(JSON.stringify({ error: "payload_too_large" }));
            return;
        }
        chunks.push(chunk);
    });
    request.on("end", function onEnd() {
        if (rejected) {
            return;
        }
        try {
            const body = JSON.parse(Buffer.concat(chunks).toString("utf8")) as StatusUpdate;
            latest.push(body);
            response.writeHead(201, { "content-type": "application/json" });
            response.end(JSON.stringify({ status: body.message }));
        } catch {
            response.writeHead(400, { "content-type": "application/json" });
            response.end(JSON.stringify({ error: "invalid_json" }));
        }
    });
});
